import os
import time
import logging
from datetime import datetime
from zk import ZK, const
import requests

# ===================== CONFIG =====================
DEVICE_IP = "172.16.1.207"
DEVICE_PORT = 4370
LARAVEL_API_URL = "https://hrp.stjosephhospitalmoshi.or.tz/api/attendance/receive"
LAST_SYNC_FILE = "last_sync.txt"
LOG_FILE = "sync.log"
SYNC_INTERVAL = 300  # 5 minutes in seconds
# API key generated by the Laravel application, sent as the `X-API-Key` header.
# Taken from the ZKTECO_API_KEY environment variable, or else from the first line of
# zkteco_api_key.txt next to this script. Never put the key in this file.
API_KEY_ENV = "ZKTECO_API_KEY"
API_KEY_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "zkteco_api_key.txt")
REQUEST_TIMEOUT = 30  # seconds
# ===================================================

# Setup logging
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)

def get_api_key():
    """Returns the TS HOSPI key from the environment or the key file, or '' if not set."""
    key = os.environ.get(API_KEY_ENV, "").strip()
    if key:
        return key
    if os.path.exists(API_KEY_FILE):
        with open(API_KEY_FILE, "r", encoding="utf-8") as f:
            return f.readline().strip()
    return ""

def get_last_sync_time():
    """Reads last sync time from file or creates it with a default old date."""
    if not os.path.exists(LAST_SYNC_FILE):
        logging.warning("last_sync.txt not found. Creating with default old date.")
        with open(LAST_SYNC_FILE, "w") as f:
            f.write("2026-06-01 00:00:00")
        return datetime(2026, 1, 1, 0, 0, 0)

    with open(LAST_SYNC_FILE, "r") as f:
        return datetime.strptime(f.read().strip(), "%Y-%m-%d %H:%M:%S")

def update_last_sync_time(dt):
    """Updates last sync time in file."""
    with open(LAST_SYNC_FILE, "w") as f:
        f.write(dt.strftime("%Y-%m-%d %H:%M:%S"))

def sync_attendance():
    """Connects to ZKTeco device, fetches new logs, sends to TS HOSPI."""
    try:
        logging.info("Starting attendance sync...")
        logging.info(f"Attempting to connect to device {DEVICE_IP}:{DEVICE_PORT}")
        zk = ZK(DEVICE_IP, port=DEVICE_PORT, timeout=50, password=0, force_udp=False, ommit_ping=False)
        
        conn = zk.connect()
        last_sync = get_last_sync_time()

        new_logs = []
        for att in conn.get_attendance():
            att_time = att.timestamp
            if att_time > last_sync:
                new_logs.append({
                    "user_id": att.user_id,
                    "timestamp": att_time.strftime("%Y-%m-%d %H:%M:%S"),
                })

        if not new_logs:
            logging.info("No new attendance logs found.")
            conn.disconnect()
            return

        logging.info(f"Found {len(new_logs)} new logs. Sending to TS HosPi...")

        api_key = get_api_key()
        if not api_key:
            # Without a key Laravel rejects the request, so keep the logs for the next run
            logging.error(f"No API key set. Set {API_KEY_ENV} or create {API_KEY_FILE}. Logs not sent.")
            conn.disconnect()
            return

        headers = {
            "Accept": "application/json",
            "X-API-Key": api_key,
        }
        response = requests.post(LARAVEL_API_URL, json=new_logs, headers=headers, timeout=REQUEST_TIMEOUT)
        if response.status_code == 200:
            logging.info("Logs synced successfully.")
            latest_time = max(datetime.strptime(log["timestamp"], "%Y-%m-%d %H:%M:%S") for log in new_logs)
            update_last_sync_time(latest_time)
        elif response.status_code == 401:
            logging.error("Unauthorized (401): the API key is missing or does not match the one TS HosPi generated.")
        elif response.status_code == 403:
            logging.error(f"Forbidden (403): TS HosPi refused this client. Response: {response.text}")
        else:
            logging.error(f"Failed to sync logs. Status: {response.status_code}, Response: {response.text}")

        conn.disconnect()

    except Exception as e:
        logging.exception(f"Error during sync: {str(e)}")

if __name__ == "__main__":
    while True:
        sync_attendance()
        logging.info(f"Next sync in {SYNC_INTERVAL/60} minutes...")
        time.sleep(SYNC_INTERVAL)
